{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    for key in ('nodes', 'core_distance', 'distances'):
        if key not in case:
            raise ValueError('missing required field: ' + key)

    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    if not isinstance(nodes, list) or not nodes:
        raise ValueError('nodes must be a non-empty list')
    if any(not isinstance(node, str) for node in nodes) or len(set(nodes)) != len(nodes):
        raise ValueError('nodes must contain unique strings')
    if not isinstance(core, dict):
        raise ValueError('core_distance must be an object')
    if set(core) != set(nodes):
        raise ValueError('core_distance keys must match nodes')
    if not isinstance(distances, list):
        raise ValueError('distances must be a list')

    def valid_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    for node in nodes:
        if not valid_number(core[node]):
            raise ValueError('invalid core distance')

    edges = []
    seen_pairs = set()
    node_set = set(nodes)
    for position, item in enumerate(distances):
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError('each distance must be a three-item array')
        left, right, distance = item
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError('distance endpoints must be strings')
        if left not in node_set or right not in node_set or left == right:
            raise ValueError('invalid distance endpoint')
        if not valid_number(distance):
            raise ValueError('invalid distance')
        first, second = (left, right) if left < right else (right, left)
        pair = (first, second)
        if pair in seen_pairs:
            raise ValueError('duplicate undirected distance')
        seen_pairs.add(pair)
        weight = max(core[left], core[right], distance)
        edges.append((weight, first, second, position))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2], edge[3]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    selected = []
    total_weight = 0
    for weight, left, right, _ in edges:
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            continue
        if rank[root_left] < rank[root_right]:
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        selected.append([left, right, weight])
        total_weight += weight
        if len(selected) == len(nodes) - 1:
            break

    if len(selected) != len(nodes) - 1:
        raise ValueError('distance graph is disconnected')
    return {'mst_edges': selected, 'total_weight': total_weight}
